import crypto from "node:crypto";import { prisma } from "@/lib/prisma";import { mobileApiError,mobileJson,mobileOptions,requireMobileUser } from "@/lib/mobile-api";import { emitToVideoLive } from "@/lib/realtime";
import { finalizeExpiredPkSessions } from "@/lib/live-maintenance";
export function OPTIONS(){return mobileOptions()}const dto=p=>({id:p.id,status:p.status,leftLiveId:p.leftSession.publicId,rightLiveId:p.rightSession.publicId,leftScore:p.leftScore.toString(),rightScore:p.rightScore.toString(),revision:p.revision,startedAt:p.startedAt?.toISOString()??null,endsAt:p.endsAt?.toISOString()??null,endedAt:p.endedAt?.toISOString()??null,winnerLiveId:p.winnerLiveId});
export async function GET(request,{params}){try{await requireMobileUser(request);await finalizeExpiredPkSessions();const{liveId}=await params,p=await prisma.videoLivePkSession.findFirst({where:{status:{in:["PENDING","LIVE"]},OR:[{leftSession:{publicId:decodeURIComponent(liveId)}},{rightSession:{publicId:decodeURIComponent(liveId)}}]},include:{leftSession:true,rightSession:true}});return mobileJson({success:true,data:{pk:p?dto(p):null}})}catch(e){return mobileApiError(e,"LIVE_PK_READ_FAILED")}}
export async function POST(request,{params}){try{const user=await requireMobileUser(request),{liveId}=await params,body=await request.json(),left=await prisma.videoLiveSession.findUnique({where:{publicId:decodeURIComponent(liveId)}}),right=await prisma.videoLiveSession.findUnique({where:{publicId:String(body?.opponentLiveId??"")}});if(!left||left.status!=="LIVE"||left.hostId!==user.id)throw new Error(left?"LIVE_HOST_REQUIRED":"LIVE_NOT_FOUND");if(!right||right.status!=="LIVE"||right.id===left.id)throw new Error("LIVE_NOT_FOUND");const conflict=await prisma.videoLivePkSession.findFirst({where:{status:{in:["PENDING","LIVE"]},OR:[{leftSessionId:{in:[left.id,right.id]}},{rightSessionId:{in:[left.id,right.id]}}]}});if(conflict)throw Object.assign(new Error("A live is already in PK."),{code:"PK_CONFLICT"});const p=await prisma.videoLivePkSession.create({data:{id:`VPK-${crypto.randomUUID().replaceAll("-","").slice(0,12).toUpperCase()}`,leftSessionId:left.id,rightSessionId:right.id},include:{leftSession:true,rightSession:true}}),data=dto(p);emitToVideoLive(left.publicId,"live-video:pk-invited",{success:true,data});emitToVideoLive(right.publicId,"live-video:pk-invited",{success:true,data});return mobileJson({success:true,data},201)}catch(e){return mobileApiError(e,"LIVE_PK_CREATE_FAILED")}}
export async function PATCH(request,{params}){try{const user=await requireMobileUser(request),{liveId}=await params,body=await request.json(),live=await prisma.videoLiveSession.findUnique({where:{publicId:decodeURIComponent(liveId)}});if(!live||live.hostId!==user.id)throw new Error(live?"LIVE_HOST_REQUIRED":"LIVE_NOT_FOUND");const p=await prisma.videoLivePkSession.findFirst({where:{id:String(body?.pkId??""),OR:[{leftSessionId:live.id},{rightSessionId:live.id}]},include:{leftSession:true,rightSession:true}});if(!p)throw Object.assign(new Error("PK not found."),{code:"PK_NOT_FOUND"});const action=String(body?.action??"").toUpperCase(),now=new Date();let data={revision:{increment:1}};if(action==="ACCEPT"&&p.status==="PENDING"&&p.rightSessionId===live.id)data={...data,status:"LIVE",startedAt:now,endsAt:new Date(now.getTime()+Math.min(1800,Math.max(60,Number(body?.durationSeconds)||300))*1000)};else if(action==="REJECT"&&p.status==="PENDING")data={...data,status:"REJECTED",endedAt:now};else if(action==="END"&&["PENDING","LIVE"].includes(p.status))data={...data,status:"ENDED",endedAt:now,winnerLiveId:p.leftScore===p.rightScore?null:(p.leftScore>p.rightScore?p.leftSession.publicId:p.rightSession.publicId)};else throw Object.assign(new Error("Invalid PK state."),{code:"PK_STATE_INVALID"});const updated=await prisma.videoLivePkSession.update({where:{id:p.id},data,include:{leftSession:true,rightSession:true}}),payload=dto(updated);emitToVideoLive(p.leftSession.publicId,"live-video:pk-changed",{success:true,data:payload});emitToVideoLive(p.rightSession.publicId,"live-video:pk-changed",{success:true,data:payload});return mobileJson({success:true,data:payload})}catch(e){return mobileApiError(e,"LIVE_PK_UPDATE_FAILED")}}
